  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ Word, PowerPoint → PDF, Fotos → PDF, gescanntes Papier → bearbeitbares Word, Excel ↔ CSV ↔ JSON, E-Books, Webseiten, Untertitel, PDFs zusammenfügen und teilen – auf deinem Handy. Deine Dateien werden nie auf eine Konverter-Website hochgeladen.",
