  "The translation appears here": "Die Übersetzung erscheint hier",
  "Every part is checked: numbers, names and codes kept exactly.": "Jeder Teil wird geprüft: Zahlen, Namen und Codes bleiben exakt erhalten.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "Öffne ein PDF, eine Word-Datei, ein Buch oder eine Webseite. Lies es hier und chatte damit – jede Antwort zeigt die Seite, aus der sie stammt. Alles bleibt auf deinem Handy.",
  "Open a file": "Datei öffnen",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "Lesen und Suchen klappen schon. Um mit der Datei zu chatten, installier ein Modell in Engine.",
  "Your documents appear here": "Deine Dokumente erscheinen hier",
  "Open a file: it is kept on this device, with its chat and notes, so you can come back to it.": "Öffne eine Datei: Sie bleibt mit Chat und Notizen auf diesem Gerät, damit du später weitermachen kannst.",
  "Stop": "Stopp",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "Beschreib es in einem Satz – die KI auf deinem Handy schreibt eine gestaltete PowerPoint oder einen kompletten Bericht, aus dem Web oder aus deiner eigenen Datei. Bearbeite jede Folie und speicher sie dann als PowerPoint, Word oder PDF.",
  "Presentation": "Präsentation",
  "Report": "Bericht",
  "e.g. A pitch for our café to offices in New Cairo: menu, catering, prices, why us": "z. B. Ein Pitch für unser Café an Büros in New Cairo: Speisekarte, Catering, Preise, warum wir",
  "Research the web for facts and figures": "Fakten und Zahlen im Web recherchieren",
  "Each slide names its sources, and a Sources slide lists every page": "Jede Folie nennt ihre Quellen, und eine Quellen-Folie listet jede Seite auf",
  "Base it on my file (Word, PDF, Excel, CSV…)": "Auf meiner Datei aufbauen (Word, PDF, Excel, CSV…)",
  "Make the presentation": "Präsentation erstellen",
  "{n} slides": "{n} Folien",
  "Midnight": "Mitternacht",
  "Short points": "Kurze Punkte",
  "Change": "Ändern",
  "Your slides appear here": "Deine Folien erscheinen hier",
  "Each slide or section shows here as it is written.": "Jede Folie oder jeder Abschnitt erscheint hier, sobald er geschrieben ist.",
  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "Erstell einen Lebenslauf auf Englisch oder Arabisch, behalt eine Kopie für jede Stelle und exportier ein sauberes PDF oder Word. Die KI auf deinem Handy hilft bei den Formulierungen.",
  "New CV": "Neuer Lebenslauf",
  "Import my CV": "Meinen Lebenslauf importieren",
  "No CVs yet": "Noch keine Lebensläufe",
  "Start a new one, or import the one you already have.": "Fang einen neuen an oder importier den, den du schon hast.",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "Kopier den Link eines Videos, füg ihn hier ein, wähl die Qualität – es wird im Filme-Ordner deines Handys gespeichert. Klappt mit direkten Videolinks, Google Drive, Dropbox, archive.org, Wikimedia Commons und Seiten, die ein einfaches Video zeigen.",
  "Find the video": "Video finden",
  "The video's versions appear here": "Die Versionen des Videos erscheinen hier",
  "Paste a link and tap Find the video — then pick the quality to download.": "Füg einen Link ein und tipp auf Video finden – dann wähl die Qualität zum Herunterladen.",
  "No map on this device yet": "Noch keine Karte auf diesem Gerät",
  "Download the world map to see every country, or your country's map for streets, places and offline search.": "Lade die Weltkarte, um jedes Land zu sehen, oder die Karte deines Landes für Straßen, Orte und Offline-Suche.",
  "Download the world map": "Weltkarte herunterladen",
