  "online": "online",
  "Search a place and tap “Save” — saved places work with no signal.": "Such einen Ort und tipp auf „Speichern“ – gespeicherte Orte funktionieren auch ohne Netz.",
  "Flight delayed or cancelled?": "Flug verspätet oder gestrichen?",
  "See what the airline owes you — up to €600 — and get the letter": "Sieh, was dir die Airline schuldet – bis zu 600 € – und hol dir den Brief",
  "Add where you fly from and the dates above.": "Trag oben deinen Abflugort und die Daten ein.",
