  "Download once on Wi-Fi — everything then works on a plane, in a tunnel, or with roaming switched off.": "Einmal im WLAN herunterladen – danach klappt alles im Flugzeug, im Tunnel oder mit ausgeschaltetem Roaming.",
  "Find a country…": "Land finden…",
  "Country packs": "Länderpakete",
