  "AI Compress": "KI-Kürzen",
  "Port": "Übertragen",
  "= instant filler removal (offline).": "= sofortiges Entfernen von Füllwörtern (offline).",
  "= the model rewrites it far shorter while keeping the meaning.": "= das Modell schreibt es viel kürzer um und behält den Sinn.",
  "Result": "Ergebnis",
  "Paste a wordy prompt and hit": "Füg einen wortreichen Prompt ein und tipp auf",
  "— it thinks about meaning, not just filler words.": "– es denkt über den Sinn nach, nicht nur über Füllwörter.",
  "Text to rewrite": "Text zum Umschreiben",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "Füg KI-generierten oder steifen Text ein – er kommt zurück, als hätte ihn ein Mensch geschrieben.",
  "Your writing sample": "Deine Schreibprobe",
  "(this is what makes it sound like you)": "(dadurch klingt es nach dir)",
  "Paste a few paragraphs you wrote yourself — an email, a message, anything in your natural voice.": "Füg ein paar Absätze ein, die du selbst geschrieben hast – eine E-Mail, eine Nachricht, irgendwas in deinem natürlichen Ton.",
  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "Behält deine Aussage und Fakten exakt bei – ändert nur, wie es sich liest. Die Schreibprobe ist optional, macht aber den größten Unterschied.",
  "Rewritten": "Umgeschrieben",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "Füg steifen oder nach KI klingenden Text ein, gib eine Probe deines eigenen Schreibstils dazu, und er kommt in deinem Ton zurück – gleicher Sinn, menschlicher Rhythmus.",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "Chatte über Attune – es liest das ganze Gespräch und schärft jeden nächsten Prompt.",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "Was willst du aus diesem ganzen Gespräch herausholen? (optional, macht aber jeden Prompt besser)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "Hol den Chat aus {t} – füg das ganze Gespräch oder nur die letzte Antwort ein:",
  "Paste here…": "Hier einfügen…",
  "Read it & suggest my reply": "Lesen & Antwort vorschlagen",
  "What do you want to ask? Type it however you like.": "Was willst du fragen? Schreib es, wie du magst.",
  "Optimize my prompt": "Meinen Prompt optimieren",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "Die Schleife: Absicht eintippen → optimierten Prompt bekommen → senden → Antwort zurückholen → jeder nächste Prompt wird schärfer. In der Handy-App ersetzt das Teilen-Menü Kopieren und Einfügen komplett.",
  "Ready prompt recipes — pick one, fill the blanks, then": "Fertige Prompt-Rezepte – wähl eins, füll die Lücken aus, dann",
  "to tailor it.": "zum Anpassen.",
  "· check updates": "· nach Updates suchen",
  "Writing & Email": "Schreiben & E-Mail",
  "Business & Work": "Business & Arbeit",
  "Study & Research": "Lernen & Forschung",
