  "Polish an email": "E-Mail aufpolieren",
  "Refines fluency, keeps your meaning": "Macht es flüssiger, behält deine Aussage",
  "Explicit action verbs beat vague asks (Anthropic 2026)": "Klare Handlungsverben schlagen vage Bitten (Anthropic 2026)",
  "Use recipe": "Rezept nutzen",
