  "Calm, firm, keeps the relationship": "Ruhig, bestimmt, die Beziehung bleibt intakt",
  "State the desired outcome, not steps (OpenAI 2026)": "Nenn das gewünschte Ergebnis, nicht die Schritte (OpenAI 2026)",
  "Shorten without losing meaning": "Kürzen, ohne Sinn zu verlieren",
  "Cuts length, keeps every point": "Macht es kürzer, behält jeden Punkt",
  "Concise prompts cut cost ~76% and lift quality": "Knappe Prompts senken die Kosten um ca. 76% und heben die Qualität",
  "Rewrite in my own voice": "In meinem eigenen Ton umschreiben",
  "Matches how you actually write": "Passt dazu, wie du wirklich schreibst",
  "Style examples outperform adjectives like 'professional'": "Stilbeispiele wirken besser als Adjektive wie „professionell“",
  "Fix tone without changing content": "Ton korrigieren, ohne den Inhalt zu ändern",
  "Same substance, better delivery": "Gleicher Inhalt, bessere Wirkung",
  "Scoping the edit prevents unwanted rewrites": "Eine klar abgegrenzte Änderung verhindert ungewolltes Umschreiben",
  "Apologize / deliver bad news": "Sich entschuldigen / schlechte Nachrichten überbringen",
  "Honest, not grovelling": "Ehrlich, nicht unterwürfig",
  "Naming the goal and constraint shapes register": "Ziel und Rahmen zu nennen prägt den Tonfall",
  "Write a speech or toast": "Eine Rede oder einen Toast schreiben",
  "Personal, not generic": "Persönlich, nicht allgemein",
  "Specific details produce specific writing": "Konkrete Details ergeben konkrete Texte",
  "Turn notes into prose": "Notizen in Fließtext verwandeln",
  "Messy notes → finished text": "Chaotische Notizen → fertiger Text",
  "Structure-to-prose is a well-suited LLM task": "Aus Stichpunkten Fließtext machen liegt einem LLM besonders gut",
  "Recipes ship with the app and work offline.": "Die Rezepte kommen mit der App und funktionieren offline.",
  "Ask it anything.": "Frag es alles.",
  "It answers from this device, and it can look through everything you've asked it before — so questions about your own work have real answers, not guesses.": "Es antwortet von diesem Gerät aus und kann alles durchsehen, was du es schon gefragt hast – Fragen zu deiner eigenen Arbeit bekommen also echte Antworten statt Vermutungen.",
  "What did I ask about last week?": "Was habe ich letzte Woche gefragt?",
  "Explain this in simple terms: …": "Erklär das einfach: …",
  "Write a short reply saying no, politely": "Schreib eine kurze, höfliche Absage",
  "What do I still owe people?": "Was schulde ich anderen noch?",
  "Convert 250 kg to pounds": "Rechne 250 kg in Pfund um",
  "Ask anything — Enter to send, Shift+Enter for a new line": "Frag alles – Enter zum Senden, Umschalt+Enter für eine neue Zeile",
  "Look it up on the web": "Im Web nachschlagen",
  "Think first": "Erst nachdenken",
  "Runs on this device · no account · works with no signal": "Läuft auf diesem Gerät · kein Konto · klappt auch ohne Netz",
  "Your own systems — like Microsoft Access, on your phone": "Deine eigenen Systeme – wie Microsoft Access, auf deinem Handy",
  "Shop in your pocket": "Der Laden in der Hosentasche",
  "Say what your shop is — the counter with barcodes, stock, customers who owe, staff and the end-of-day close, ready in a minute. Every sale goes into your books.": "Sag, was für ein Laden du hast – Kasse mit Barcodes, Lager, Kunden mit offenen Beträgen, Personal und Tagesabschluss, in einer Minute fertig. Jeder Verkauf landet in deiner Buchhaltung.",
  "Start a new system": "Neues System starten",
