  "Invoices with VAT, payments and overdue tracking, stock and purchasing, reports — your own accounting, on your phone, in English and Arabic.": "Rechnungen mit MwSt., Zahlungen und Mahnwesen, Lager und Einkauf, Berichte – deine eigene Buchhaltung, auf deinem Handy, auf Englisch und Arabisch.",
  "Your systems": "Deine Systeme",
  "Open an app file": "App-Datei öffnen",
