  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "Zu schwer für ein Handy – es kann die App schließen. Core oder Blaze laufen hier flüssig; dieses gibt's in der Desktop-App.",
