  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro kaufst du in der Google-Play-Version von Attune – mit einem Tippen, per Karte oder über dein Vodafone-/Orange-/Etisalat-Guthaben bezahlt, und es schaltet sich von selbst ein.",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Jederzeit kündbar unter Google Play → Abos. Der Tarif verlängert sich von selbst; nichts zu senden, niemandem zu schreiben.",
