  "Nothing to read in that.": "Da gibt es nichts zu lesen.",
  "That payment did not go through, so there is nothing to record.": "Diese Zahlung ist nicht durchgegangen, es gibt also nichts einzutragen.",
  "Sent to Yusr — pick the account and confirm": "An Yusr gesendet – wähle das Konto und bestätige",
  "Money isn't bundled in this build.": "Geld ist in dieser Version nicht enthalten.",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "Das Yusr-Dokument wurde nicht eingebettet. Auf dem Handy wird es aus den App-Dateien geladen.",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "Dein Kassenbuch und jede Zakat-Regel sind hier, unverändert und für immer gratis. Attune ergänzt Gedächtnis und einfache Sprache – es berechnet nie die Zakat und bewegt nie selbst Geld.",
  "Share a payment": "Zahlung teilen",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "Eine InstaPay-Bestätigung, eine Bank-SMS, ein Wallet-Beleg oder ein Foto davon. Attune liest den Betrag und den Empfänger und öffnet dann dein eigenes Buchungsblatt, schon ausgefüllt. Das Konto wählst du.",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321",
  "Read it": "Lesen",
  "Reading…": "Wird gelesen …",
  "From a photo": "Aus einem Foto",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "Drei Wege, alle gut: Teile die SMS, WhatsApp-Nachricht oder den Screenshot aus jeder App mit Attune (er landet von selbst hier) · füge ihn oben ein · oder fotografiere den Beleg bzw. wähle ein Foto.",
  "read from: “": "gelesen aus: „",
  "· account: you choose, in Yusr": "· Konto: wählst du in Yusr",
  "Talk to your money": "Sprich mit deinem Geld",
  "not saved to memory": "nicht im Gedächtnis gespeichert",
  "saved to memory": "im Gedächtnis gespeichert",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "Auf diesem Gerät beantwortet, mit den Zahlen, die Yusr berechnet hat. Stell Nachfragen – der Verlauf bleibt erhalten. Bei der Zakat bekommt es die Zahlen der App und darf sie nicht neu berechnen: Es erklärt, es urteilt nicht.",
  "figures from Yusr's zakāt engine, not recalculated": "Zahlen aus Yusrs Zakat-Rechner, nicht neu berechnet",
  "ask a follow-up…": "Nachfrage stellen …",
  "Thinking…": "Denke nach …",
  "What do you make of this?": "Was hältst du davon?",
