  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "Jeder Bereich, den du ansiehst, wird gespeichert und funktioniert so auch ohne Netz. Du kannst einen Bereich auch vor der Reise herunterladen. Die Ortssuche braucht eine Verbindung; deine gespeicherten Orte sind auch ohne durchsuchbar.",
  "offline — showing saved tiles": "offline – gespeicherte Kacheln werden angezeigt",
