  "Translated by the AI on your phone — check important names and numbers.": "Von der KI auf deinem Handy übersetzt – prüfe wichtige Namen und Zahlen.",
  "Translating needs an AI model — open Engine and install one.": "Zum Übersetzen braucht es ein KI-Modell – öffne Engine und installiere eins.",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "Die KI auf deinem Handy übersetzt Stück für Stück; Überschriften, Listen, Tabellen und Zahlen bleiben an ihrem Platz. Lange Dateien dauern ein paar Minuten.",
