  "For power users. Community models are not tested by Attune: a model bigger than about 40% of this phone's memory will run slowly and hot, or be closed by Android. Check the size on its Hugging Face page first, and prefer the Q4 file.": "Für Profis. Community-Modelle testet Attune nicht: Ein Modell, das größer als etwa 40 % des Speichers dieses Handys ist, läuft langsam und heiß oder wird von Android beendet. Prüfe zuerst die Größe auf seiner Hugging-Face-Seite und nimm lieber die Q4-Datei.",
