  "Tap to copy. These are written by hand, not generated — so an allergy or emergency phrase can never come out wrong.": "Tippen zum Kopieren. Diese Sätze sind von Hand geschrieben, nicht generiert – ein Allergie- oder Notfallsatz kann also nie falsch herauskommen.",
