  "Delete": "Löschen",
  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "Installierte Gewichte aktualisieren sich nie von selbst. Ein Prompt, der heute funktioniert, funktioniert also auch in einem Jahr noch genauso. Der Fingerabdruck beweist, welche Datei genau antwortet.",
  "Add any model": "Beliebiges Modell hinzufügen",
  "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   or   https://…/model.gguf": "unsloth/Qwen3.5-9B-GGUF:Q4_K_M   oder   https://…/model.gguf",
  "Any GGUF on Hugging Face as": "Jede GGUF-Datei auf Hugging Face als",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", oder ein direkter https-Link. Spezialisierte und feinabgestimmte Modelle werden genauso installiert – der Foto-Reader wird mitgeladen, wenn das Repo einen hat.",
  "How it answers": "So antwortet es",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "z. B. Ich führe einen kleinen Laden in Ägypten. Antworte auf Ägyptisch-Arabisch, außer ich schreibe auf Englisch. Nenne Preise in EGP.",
  "Saved when you tap outside the box. Stays on this phone.": "Wird gespeichert, wenn du außerhalb des Felds tippst. Bleibt auf diesem Handy.",
  "Web lookup": "Websuche",
  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "Nur die Frage, die du nachschlägst, und die geöffneten Seiten verlassen das Handy – nie dein Gespräch, deine Dateien oder dein Gedächtnis.",
  "Hide network log": "Netzwerkprotokoll ausblenden",
  "made ·": "hergestellt ·",
  "blocked · this session": "blockiert · diese Sitzung",
  "Nothing has left the phone.": "Nichts hat das Handy verlassen.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \"nothing leaves this phone\".": "Das Modell selbst nutzt nie das Netzwerk. Das Protokoll listet jede Verbindung, die die App hergestellt oder abgelehnt hat, nur mit Host und Grund – der Beweis für „nichts verlässt dieses Handy“.",
