  "Merge": "Zusammenführen",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Behalte alles auf diesem Handy und füge die Chats, das Gedächtnis, die Erinnerungen und die Zyklustage der Sicherung hinzu. Das Geld-Journal wird nur dann aus der Sicherung übernommen, wenn dieses Handy keins hat.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "Die {c} Chats und {l} Journaleinträge dieses Handys werden durch die der Sicherung ersetzt. Du kannst das direkt danach einmal rückgängig machen.",
  "The backup's items will be added to this phone. You can undo this once, right after.": "Die Einträge der Sicherung werden zu diesem Handy hinzugefügt. Du kannst das direkt danach einmal rückgängig machen.",
