  "What do you work in?": "In welchem Bereich arbeitest du?",
  "What will you use Attune for?": "Wofür willst du Attune nutzen?",
  "What's your role?": "Was ist deine Rolle?",
  "Which languages do you use?": "Welche Sprachen sprichst du?",
  "Name the outcome; it fills in the path.": "Nenne das Ergebnis, den Weg findet es selbst.",
  "Huge window — compress for cost, not for fit.": "Riesiges Kontextfenster – komprimiere wegen der Kosten, nicht wegen des Platzes.",
  "Direct phrasing; ask for reasoning explicitly.": "Direkt formulieren; Begründungen ausdrücklich verlangen.",
  "Structured reasoning; keep numbered steps.": "Strukturiertes Denken; nummerierte Schritte beibehalten.",
  "Strong multilingual — keep the source language.": "Stark mehrsprachig – die Ausgangssprache beibehalten.",
  "Concise by nature; over-compressing loses nuance.": "Von Natur aus knapp; zu starkes Kürzen kostet Nuancen.",
  "Open weights; explicit instructions beat implied ones.": "Offene Gewichte; ausdrückliche Anweisungen schlagen angedeutete.",
  "Long documents are its strength; keep headings.": "Seine Stärke sind lange Dokumente; Überschriften beibehalten.",
  "Code context competes for the window — trim prose first.": "Code-Kontext konkurriert um das Fenster – kürze zuerst den Fließtext.",
  "A search tool — keep the sources, cut the styling.": "Zuerst eine Suchmaschine – Quellen behalten, Styling streichen.",
  "Tight. Cut everything that isn't the instruction.": "Knapp. Streiche alles, was nicht die Anweisung ist.",
  "Room for a short history, not a long one.": "Platz für einen kurzen Verlauf, nicht für einen langen.",
  "Same window; better at using what's in it.": "Gleiches Fenster; nutzt besser, was darin steht.",
  "Ed25519": "Ed25519",
  "Activated offline — it will bind to this device the next time there's a connection.": "Offline aktiviert – es wird beim nächsten Mal mit Verbindung an dieses Gerät gebunden.",
  "Couldn't reach activation — running on the key's signature for now.": "Aktivierung nicht erreichbar – vorerst läuft es mit der Signatur des Schlüssels.",
