  "No model is loaded. Open Engine in Attune and load one.": "Kein Modell geladen. Öffne Engine in Attune und lade eins.",
  "Attune does not answer that kind of request.": "Attune beantwortet diese Art von Anfrage nicht.",
  "Suggested. The free tier stops when it runs out instead of charging you.": "Empfohlen. Die kostenlose Stufe hört auf, wenn sie aufgebraucht ist, statt dir etwas zu berechnen.",
  "Needs a card on file. An independent index — good in English, unproven in Arabic.": "Braucht eine hinterlegte Karte. Ein unabhängiger Index – gut auf Englisch, auf Arabisch unerprobt.",
  "Returns Google's own results, so the best Arabic quality of the three.": "Liefert Googles eigene Ergebnisse, daher die beste Qualität auf Arabisch von den dreien.",
