  "On-device": "Auf dem Gerät",
  "The only mode. Nothing leaves this device.": "Der einzige Modus. Nichts verlässt dieses Gerät.",
  "Write a polite reply to this message: ": "Schreibe eine höfliche Antwort auf diese Nachricht: ",
  "Translate into English: ": "Übersetze ins Englische: ",
  "Summarise this in 3 bullets: ": "Fasse das in 3 Stichpunkten zusammen: ",
  "What should I check on a used car before I buy it?": "Worauf sollte ich bei einem Gebrauchtwagen vor dem Kauf achten?",
  "My period started this morning, medium flow": "Meine Periode hat heute Morgen angefangen, mittlere Stärke",
  "Add it to your ledger in Money? You'll pick the account and confirm there.": "Zu deinem Journal in Geld hinzufügen? Konto wählst und bestätigst du dort.",
  "Spotting": "Schmierblutung",
  "Light": "Leicht",
  "Medium": "Mittel",
  "Heavy": "Stark",
  "item": "Eintrag",
  "items": "Einträge",
  "15 questions a day": "15 Fragen pro Tag",
  "3 templates · 5 history items": "3 Vorlagen · 5 Verlaufseinträge",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B Wissen, 3B erledigen bei jedem Token die Arbeit – Antworten nahe der Spitzenklasse in einer Geschwindigkeit, die ein Laptop durchhält. Ein Mixture-of-Experts-Modell hält alle Experten im Speicher, obwohl pro Token nur wenige laufen; es braucht also den RAM eines 35B und die Rechenleistung eines 3B.",
  "A bigger length budget for reports, plans and analysis.": "Ein größeres Längenbudget für Berichte, Pläne und Analysen.",
  "Ask it as much as you like — no daily limit": "Frag so viel du willst – kein Tageslimit",
  "Your phone reports {n} GB of memory": "Dein Handy meldet {n} GB Speicher",
  "Your computer reports {n} GB of memory": "Dein Computer meldet {n} GB Speicher",
  "which is comfortable for everyday use": "was für den Alltag bequem ist",
  "which is enough, with shorter conversations": "was reicht, mit kürzeren Gesprächen",
  ", ": ", ",
  "Documents, fleet records, copilot, every domain pack": "Dokumente, Fuhrparkdaten, Copilot, jedes Fachpaket",
  "Small enough to download on mobile data if you need to.": "Klein genug, um es bei Bedarf über mobile Daten herunterzuladen.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "Das ist ein großes Modell für ein Handy. Es läuft, wird aber merklich langsamer, sobald das Handy warm wird – halte die Antworten kurz oder nimm das kleinere.",
  "Every tool, and all 31 country packs": "Jedes Werkzeug und alle 31 Länderpakete",
  "Finds what you promised people, from your own words": "Findet, was du Leuten versprochen hast, aus deinen eigenen Worten",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "Feste Zufallswerte, damit ein Workflow bei jedem Lauf dieselbe Ausgabe liefert.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "Kostenlose Websuche: DuckDuckGo, Bing und Mojeek gleichzeitig, dann werden die besten Seiten ganz gelesen, damit Antworten aus echten Textstellen kommen.",
  "Free · no key": "Gratis · ohne Schlüssel",
  "Installing… {p}%": "Wird installiert… {p} %",
  "It remembers everything and can search it": "Merkt sich alles und kann es durchsuchen",
  "Learns your vocabulary and writes the way you do": "Lernt deinen Wortschatz und schreibt wie du",
  "No account, no sign-in, nothing uploaded": "Kein Konto, keine Anmeldung, nichts wird hochgeladen",
  "Running": "Läuft",
  "Loading the model…": "Modell wird geladen…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "Nichts in der App kann das Internet erreichen – keine Websuche, keine Karten, keine Downloads. Das Modell und alles auf dem Handy funktionieren weiter.",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "Das Modell denkt bei jeder Frage zuerst nach. Bei schwierigen Aufgaben deutlich besser, aber auf einem Handy beginnt die Antwort 30–90 s später. Aus: Tippe nur bei Fragen, die es brauchen, auf „Think“.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "Dasselbe Modell wie unten, mit genug Speicher, um ein ganzes Buch an Kontext auf einmal zu halten. Auf einem Rechner mit 48 GB ist der freie RAM besser in Kontext als in Präzision investiert – du kannst ihm einen ganzen Vertrag oder ein Jahr an Notizen geben, und es behält alles im Blick.",
  "The whole assistant, on your device": "Der ganze Assistent auf deinem Gerät",
  "Works entirely offline. No account, ever.": "Funktioniert komplett offline. Nie ein Konto.",
