  "That time has already passed — pick a later one.": "Diese Zeit ist schon vorbei – wähle eine spätere.",
  "That is more than a year away — check the date.": "Das ist mehr als ein Jahr entfernt – prüfe das Datum.",
  "Who should it go to?": "An wen soll es gehen?",
