  "What are the key points?": "Was sind die wichtigsten Punkte?",
  "Checklist: what every answer must satisfy (one per line, optional)": "Checkliste: Was jede Antwort erfüllen muss (eine pro Zeile, optional)",
  "Facts the AI should know (prices, rules, terms — optional)": "Fakten, die die KI kennen soll (Preise, Regeln, Bedingungen – optional)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Trenne Themen mit einer Leerzeile. Es werden nur die Absätze verwendet, die zur Frage passen, daher darf das lang sein.",
  "Facts": "Fakten",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Es führt außerdem dieses kleine Programm auf deinem Handy aus (offline, in einer abgeschlossenen Box – kein Internet, keine Dateien, kein Zugriff auf die App)",
  "Edit or improve my CV": "Meinen Lebenslauf bearbeiten oder verbessern",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Sag, was ergänzt oder geändert werden soll («füge meine Stelle im Dar Al Fouad Hospital als Krankenpfleger hinzu, 2019–2022», «ändere meine Telefonnummer in …»), oder lass es leer und mach ihn einfach professioneller. Du siehst das Ergebnis, bevor es übernommen wird.",
  "What should be added or changed? (optional)": "Was soll ergänzt oder geändert werden? (optional)",
  "Apply my change": "Meine Änderung anwenden",
  "Change + make it professional": "Ändern + professioneller machen",
  "New version": "Neue Version",
  "Use this version": "Diese Version verwenden",
  "Done — you can undo it": "Fertig – du kannst es rückgängig machen",
  "Undo the last change": "Letzte Änderung rückgängig machen",
  "Stuck — starting again from scratch with a different approach": "Festgefahren – es beginnt mit einem anderen Ansatz von vorn",
  "Wrote it, with {n} tests.": "Geschrieben, mit {n} Tests.",
