  "not passing": "nicht bestanden",
  "passing": "bestanden",
  "✓ Passed all {n} tests.": "✓ Alle {n} Tests bestanden.",
  "✓ Ran without errors.": "✓ Ohne Fehler ausgeführt.",
  "The fix did not match the code.": "Die Korrektur passte nicht zum Code.",
  "The model answered without code.": "Das Modell hat ohne Code geantwortet.",
  "The fix deleted the tests — refused.": "Die Korrektur hat die Tests gelöscht – abgelehnt.",
  "The model answered without any code — try asking again in other words.": "Das Modell hat ganz ohne Code geantwortet – frag noch einmal mit anderen Worten.",
  "A picture — Studio draws it on this phone": "Ein Bild – Studio zeichnet es auf diesem Handy",
  "Another version": "Weitere Version",
  "Could not open that picture": "Das Bild konnte nicht geöffnet werden",
  "Could not save": "Konnte nicht gespeichert werden",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Aktuelle Fotoqualität in 4 Schritten: Menschen, Orte, Produkte und Text in Bildern. Bearbeitet auch ein Foto, das du ihm gibst („mach es Nacht“, „entferne das Auto“).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Beschreibe das Bild auf Arabisch oder Englisch – z. B. „eine Feluke auf dem Nil bei Sonnenuntergang“",
  "Developing the picture…": "Das Bild wird entwickelt…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Lade es per WLAN herunter. Danach entstehen Bilder ganz ohne Internet.",
  "Draw it": "Zeichnen",
  "Draw it in Studio": "In Studio zeichnen",
  "A place — Maps finds it": "Ein Ort – Karten findet ihn",
  "Show on the map": "Auf der Karte zeigen",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Auf dem Grafikchip zeichnen (schneller; schaltet sich selbst aus, wenn der Treiber versagt)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Das Zeichnen auf der GPU ist fehlgeschlagen, deshalb hat Attune Studio auf die CPU umgestellt. ",
  "Drawing — step {n} of {t}": "Zeichnen – Schritt {n} von {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Jedes Bild entsteht in einem eigenen Engine-Prozess: Wenn er fertig ist, geht sein gesamter Speicher ans Handy zurück. Nichts wird hochgeladen.",
  "Edit a photo": "Foto bearbeiten",
  "Edit it": "Bearbeiten",
  "Edit this": "Das bearbeiten",
  "GB, once": "GB, einmalig",
  "Install the picture model first (Studio).": "Installiere zuerst das Bildmodell (Studio).",
  "Install the sharpening model first (Studio).": "Installiere zuerst das Schärfungsmodell (Studio).",
