  "Save to gallery": "In Galerie speichern",
  "Saved to {w}": "Gespeichert in {w}",
  "Saving to the gallery needs Android 10 or newer — use Share instead.": "Das Speichern in der Galerie braucht Android 10 oder neuer – nutze stattdessen Teilen.",
  "Saving…": "Wird gespeichert…",
  "Sharpening ×4": "Schärfen ×4",
  "Sharpening ×4 — part {n} of {t}": "Schärfen ×4 – Teil {n} von {t}",
  "Square": "Quadrat",
  "Starting the download…": "Download wird gestartet…",
  "Starting the picture engine…": "Bild-Engine wird gestartet…",
  "Studio works in the Android app.": "Studio funktioniert in der Android-App.",
  "The chat model was paused to make room, and is loading again.": "Das Chat-Modell wurde pausiert, um Platz zu schaffen, und lädt gerade wieder.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "Dieses APK hat noch keine Bild-Engine – sie kommt mit dem nächsten APK von GitHub.",
  "This build draws on the CPU.": "Dieser Build zeichnet auf der CPU.",
  "This build of the app has no picture engine yet.": "Dieser Build der App hat noch keine Bild-Engine.",
  "This phone has {n} GB — it may be too little for pictures.": "Dieses Handy hat {n} GB – das ist für Bilder womöglich zu wenig.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Diese Version von Attune hat keine Bild-Engine für den Grafikchip, deshalb werden Bilder auf der CPU gezeichnet (langsamer). Ein Update bringt sie.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "Die Bild-Engine hat beim Laden des Modells nicht mehr reagiert und wurde gestoppt. Engine → Engine-Protokoll zeigt ihre letzten Zeilen – sende sie an den Support.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "Der GPU-Treiber dieses Handys hat nicht geantwortet, deshalb werden Bilder auf der CPU gezeichnet (langsamer).",
  "What should change? e.g. “make it night, with the street lights on”": "Was soll sich ändern? z. B. „mach es Nacht, mit eingeschalteten Straßenlaternen“",
  "Write a fuller description first (better pictures; uses the chat model)": "Schreibe zuerst eine ausführlichere Beschreibung (bessere Bilder; nutzt das Chat-Modell)",
  "Writing a fuller description…": "Ausführlichere Beschreibung wird geschrieben…",
  "needs {n} GB RAM": "braucht {n} GB RAM",
  "{m} is ready": "{m} ist bereit",
  "×4 sharper": "×4 schärfer",
