  "None yet — add a field of type “Link to another table”, or ask below: “connect Jobs to Customers”.": "Noch keine – füge ein Feld vom Typ „Verknüpfung mit anderer Tabelle“ hinzu oder frag unten: „verbinde Aufträge mit Kunden“.",
