  "e.g. unpaid invoices over 50,000 · jobs this month by customer · top 5 cranes by revenue": "z. B. unbezahlte Rechnungen über 50.000 · Aufträge diesen Monat nach Kunde · die 5 Krane mit dem höchsten Umsatz",
