  "Save form": "Formular speichern",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "Noch keine Formulare. Ein Formular zeigt nur die Felder, die du brauchst, in deiner Reihenfolge und mit vorbelegten Werten – wähle es beim Hinzufügen eines Eintrags.",
