  "Forms": "Formulare",
  "Open an app file (made with Attune)": "App-Datei öffnen (mit Attune erstellt)",
  "That file isn't an app made with Attune Business.": "Das ist keine mit Attune Business erstellte App.",
  "Updated from the app file — {n} tables with their records": "Aus der App-Datei aktualisiert – {n} Tabellen mit ihren Einträgen",
  "Opened — {n} tables with their records": "Geöffnet – {n} Tabellen mit ihren Einträgen",
  "Change the design in words — add fields to any table, new tables, links…": "Ändere den Entwurf in Worten – Felder zu Tabellen hinzufügen, neue Tabellen, Verknüpfungen…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "z. B. füge Lieferanten E-Mail und Steuernummer hinzu und Teilen ein Feld Garantie (Monate)",
  "Saved — send this file; it opens in any browser, no Attune needed": "Gespeichert – sende diese Datei; sie öffnet sich in jedem Browser, ohne Attune",
  "Excel files need Python, which isn't in this build — use CSV.": "Excel-Dateien brauchen Python, das nicht in diesem Build ist – nutze CSV.",
  "Making the Excel file…": "Excel-Datei wird erstellt…",
  "Couldn't make the Excel file: {e}": "Die Excel-Datei konnte nicht erstellt werden: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "Gib sie deinem Team als App: eine Datei mit allen Daten darin – sie öffnet sich im Browser jedes Handys oder Computers, ohne Attune. Wenn etwas geändert werden muss, öffne die Datei hier (Business → App-Datei öffnen), frag die KI und sende die neue App zurück.",
  "Export as an app": "Als App exportieren",
  "Excel workbook (all tables)": "Excel-Arbeitsmappe (alle Tabellen)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "Die Bild-Engine wurde gestoppt, bevor das Bild fertig war – Android hat sie womöglich beendet, um Speicher freizugeben. Versuche „Schneller Entwurf“ oder schließe andere Apps und versuche es erneut.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "Das Bild konnte nicht erstellt werden. Öffne Engine → Engine-Protokoll und schick mir, was dort steht.",
  "Multi-token prediction (faster writing)": "Multi-Token-Vorhersage (schnelleres Schreiben)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "Standardmäßig aus: Auf manchen Handys verdoppelt sie Wörter und Ziffern („ItIt is is“, „20205“). Schalte sie nur ein, wenn die Antworten korrekt bleiben.",
  "The last picture didn't finish:": "Das letzte Bild wurde nicht fertig:",
