  "Studio Turbo": "Studio Turbo",
  "Studio Pro": "Studio Pro",
  "Studio Pro HD": "Studio Pro HD",
  "Turbo · about 1 min": "Turbo · etwa 1 Min.",
  "Studio Turbo+": "Studio Turbo+",
  "Recommended for your phone": "Für dein Handy empfohlen",
  "Studio Ultra": "Studio Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · beste Qualität, langsam · {s} GB",
  "best quality, slow": "beste Qualität, langsam",
  "fastest pictures": "schnellste Bilder",
  "a graphics card with 8 GB or more: the most capable model": "eine Grafikkarte mit 8 GB oder mehr: das leistungsfähigste Modell",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "Das leistungsfähigste Modell: Text in Bildern, volle Szenen, Menschen. Auf dem Handy langsam (etwa 10 Minuten pro Bild), auf einem Computer mit Grafikkarte schnell. Braucht 12 GB RAM.",
  "about {s} s a picture": "etwa {s} s pro Bild",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB oder mehr und schnelle Kerne: das schärfere XL-Modell in einem Schritt",
  "not enough free storage or speed for the XL model": "nicht genug freier Speicher oder Tempo für das XL-Modell",
  "the fast model fits this phone's memory": "das schnelle Modell passt in den Speicher dieses Handys",
  "little memory or slow cores: smaller pictures, still clear": "wenig Speicher oder langsame Kerne: kleinere Bilder, trotzdem klar",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · etwa 20 s · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Schneller und schärfer als Turbo, mit besserer Übereinstimmung mit deiner Anfrage: etwa 20 Sekunden pro Bild auf der CPU. 512 px. Für Handys mit 8 GB RAM oder mehr.",
  "Pro · best quality": "Pro · beste Qualität",
  "Pro on this phone's CPU: 10–20 min a picture": "Pro auf der CPU dieses Handys: 10–20 Min. pro Bild",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "Der Grafikchip dieses Handys funktioniert nicht mit Studio, deshalb würde das Pro-Modell auf der CPU 10–20 Minuten pro Bild brauchen. Studio Turbo macht ein Bild in etwa einer Minute.",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "Schnelle Bilder auf jedem Handy: etwa eine Minute ohne Grafikchip, Sekunden mit einem. 512 px – ideal für Ideen, Entwürfe und Beiträge.",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "Die beste Fotoqualität: Menschen, Orte, Produkte und Text in Bildern, 1024 px. Bearbeitet auch ein Foto, das du ihm gibst („mach es Nacht“, „entferne das Auto“). Braucht einen funktionierenden Grafikchip – auf der CPU dauert ein Bild 10–20 Minuten.",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "Studio Pro in voller Präzision: feinere Details, sauberere Gesichter, Hände und Text. Bearbeitet auch deine Fotos nach Anweisung. Braucht einen funktionierenden Grafikchip und 12 GB RAM.",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "Arbeitet noch – nichts hängt. Turbo braucht auf der CPU etwa 1–2 Minuten. Lass Attune geöffnet; Stopp bricht ab.",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "Arbeitet noch – nichts hängt. Ohne Grafikchip dauert ein Pro-Bild 10–20 Minuten (Bearbeitungen länger). Für mehr Tempo wähle Turbo. Lass Attune geöffnet; Stopp bricht ab.",
  "Delete this chat?": "Diesen Chat löschen?",
  "This can't be undone.": "Das kann nicht rückgängig gemacht werden.",
  "Delete this reminder?": "Diese Erinnerung löschen?",
  "Delete this project?": "Dieses Projekt löschen?",
  "Remove this crane from the fleet?": "Diesen Kran aus dem Fuhrpark entfernen?",
  "Remove this from the project?": "Das aus dem Projekt entfernen?",
  "Delete this picture?": "Dieses Bild löschen?",
  "Delete this place?": "Diesen Ort löschen?",
  "Forget this correction?": "Diese Korrektur vergessen?",
  "Forget": "Vergessen",
  "Delete this action?": "Diese Aktion löschen?",
  "Spark (helper)": "Spark (Helfer)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "Funktioniert nur mit Spark, Glow, Core und Zenith – nicht mit dem verwendeten Modell.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Lade Spark als Helfer herunter (etwa 0,5 GB, einmalig). Funktioniert mit Glow, Core und Zenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "Das ist ein großes Modell für ein Handy – Core ist etwa 2–3× schneller.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "Das stärkste Modell, das ein Handy mit 12 GB ausführen kann: Expertenantworten und das beste beim Lesen von Dokumenten und Fotos.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "Core um 10 % kleiner gemacht für ein Handy mit 4 GB – lohnt sich mehr als Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "Läuft auf einem günstigen Handy und liest trotzdem Fotos. Gute kurze Antworten; bei langem Nachdenken zeigt sich die Größe.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "Für ein Handy, das nichts anderes mehr verkraftet: Text glätten und kürzen. Nicht zum Nachdenken.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "Die größte Beschleunigung auf diesem Handy ist die schnelle Engine: Blaze auf dem Grafikchip – erste Wörter nach etwa einer Sekunde. Tippe oben auf „Zur schnellen Engine wechseln“.",
