  "Pro is active on this phone. Thank you for supporting Attune!": "Pro ist auf diesem Handy aktiv. Danke, dass du Attune unterstützt!",
  "Your free Pro trial: {n} days left — everything is unlocked. Keep it by choosing a plan.": "Deine kostenlose Pro-Testphase: noch {n} Tage – alles ist freigeschaltet. Behalte es, indem du einen Tarif wählst.",
  "Free gives you {n} answers a day on every model. Pro removes every limit:": "Gratis gibt dir {n} Antworten pro Tag bei jedem Modell. Pro hebt jede Grenze auf:",
