  "Put the ask after the data (Gemini/GPT guidance)": "Die Aufgabe hinter die Daten setzen (Empfehlung für Gemini/GPT)",
  "Define the output shape explicitly": "Das Ausgabeformat ausdrücklich festlegen",
  "Name the goal so the model reasons toward it": "Das Ziel nennen, damit das Modell darauf hin denkt",
  "Specificity → fewer misinterpretations": "Genauigkeit → weniger Missverständnisse",
  "Goal-framing beats tone adjectives alone": "Zielvorgabe schlägt Stimmungsadjektive allein",
  "Data first, question last improves grounding": "Erst die Daten, zuletzt die Frage – das verbessert die Verankerung",
  "Role-free outcome framing (2026 guidance)": "Ergebnisorientiert ohne Rolle (Empfehlung 2026)",
  "Explicit output shape reduces rework": "Ein ausdrückliches Ausgabeformat verringert Nacharbeit",
  "Goal + constraint framing produces usable scripts": "Ziel + Einschränkung ergeben brauchbare Skripte",
  "Stated criteria prevent generic pro/con lists": "Genannte Kriterien verhindern allgemeine Pro-und-Contra-Listen",
  "Concrete constraints beat generic advice": "Konkrete Vorgaben schlagen allgemeine Ratschläge",
  "Time constraints force actionable plans": "Zeitvorgaben erzwingen umsetzbare Pläne",
  "Matching to the posting outperforms templates": "Passend zur Stellenanzeige schlägt Vorlagen",
  "Role-specific prompting beats generic question lists": "Rollenspezifische Prompts schlagen allgemeine Fragenlisten",
  "Source-anchored prompts reduce invented detail": "Quellenbasierte Prompts verringern erfundene Details",
  "Constraints up front prevent generic travel advice": "Vorgaben vorab verhindern allgemeine Reisetipps",
  "Explaining the 'why' improves targeting (Anthropic)": "Das „Warum“ zu erklären verbessert die Zielgenauigkeit (Anthropic)",
  "Search tools need source + recency constraints": "Suchwerkzeuge brauchen Quellen- und Aktualitätsvorgaben",
  "Constraints up front prevent generic answers": "Vorgaben vorab verhindern allgemeine Antworten",
  "Active recall outperforms re-reading": "Aktives Abrufen schlägt erneutes Lesen",
  "Sectioned output aids comprehension": "Eine Ausgabe in Abschnitten hilft beim Verstehen",
  "Explicit critique requests beat 'what do you think'": "Ausdrückliche Bitten um Kritik schlagen „Was denkst du?“",
  "Naming review axes prevents shallow feedback": "Benannte Prüfachsen verhindern oberflächliches Feedback",
  "Include context + attempted fixes for accuracy": "Kontext + bisherige Lösungsversuche erhöhen die Genauigkeit",
  "Section-by-section output beats 'write a page'": "Abschnittsweise Ausgabe schlägt „schreib eine Seite“",
  "Persona-specific prompts improve targeting": "Personenspezifische Prompts verbessern die Zielgenauigkeit",
  "Stating criteria prevents generic pro/con lists": "Genannte Kriterien verhindern allgemeine Pro-und-Contra-Listen",
  "Level-setting improves explanation fit": "Das Niveau festzulegen verbessert die Passung der Erklärung",
  "Specifying length prevents rambling summaries": "Eine Längenvorgabe verhindert ausschweifende Zusammenfassungen",
  "Ask to implement, not 'suggest changes' (Anthropic)": "Um Umsetzung bitten, nicht um „Änderungsvorschläge“ (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "Reasoning-Modelle glänzen bei klarem Umfang, ohne Beispiele",
  "Name every state so nothing is left ambiguous": "Jeden Zustand benennen, damit nichts unklar bleibt",
  "Natural language + explicit variety works on GPT": "Natürliche Sprache + ausdrückliche Vielfalt funktioniert bei GPT",
  "Outcome framing beats feature lists": "Ergebnisrahmen schlägt Funktionslisten",
  "Gemini prefers direct, constrained prompts": "Gemini mag direkte Prompts mit Vorgaben",
  "Short + specific tone yields natural output": "Kurz + konkret im Ton ergibt natürliche Ausgaben",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "Chain-of-Thought: im Schnitt ca. +40 % bei schwierigem Schlussfolgern (Wei et al.); MultiArith 18 % → 79 %. Bei Reasoning-Modellen weglassen – kaum Gewinn, mehr Wartezeit.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "1–5 Beispiele (Few-Shot) steigern die Genauigkeit bei Musteraufgaben um bis zu +43 %; am besten bei Nicht-Reasoning-Modellen wie Gemini. Bei reinem Schlussfolgern keine Beispiele hinzufügen – das kann schaden.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: Beschreibe, wie ein gutes Ergebnis aussieht; zu viele Anweisungen erzeugen bei modernen Modellen nur Rauschen.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "Praxis 2026: Lege fest, wie intensiv gedacht wird (Denk-/Aufwandsregler), und investiere Worte ins Ergebnis, nicht in „denk Schritt für Schritt“.",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "Erst klären verringert verschwendete Runden – das Modell sammelt fehlenden Kontext, statt zu raten.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "Ergebniskriterien (was „gut“ heißt) schlagen bei Modellen von 2026 Prozessanweisungen.",
  "Verification steps reduce errors on factual/analytical tasks.": "Prüfschritte verringern Fehler bei sachlichen/analytischen Aufgaben.",
  "Explicit sections prevent rambling updates": "Ausdrückliche Abschnitte verhindern ausufernde Updates",
  "Asking for risks surfaces what you forgot": "Die Frage nach Risiken bringt zutage, was du vergessen hast",
  "Outcome framing keeps feedback constructive": "Ergebnisrahmen hält Feedback konstruktiv",
  "Explicit audience prevents vague procedures": "Eine ausdrückliche Zielgruppe verhindert vage Abläufe",
  "Spaced repetition beats massed practice": "Verteiltes Wiederholen schlägt Pauken",
  "Worked examples aid transfer to new problems": "Durchgerechnete Beispiele helfen beim Übertrag auf neue Probleme",
  "Planning prompts reduce rework on complex tasks": "Planungs-Prompts verringern Nacharbeit bei komplexen Aufgaben",
  "Explicitly requesting edge cases improves coverage": "Die ausdrückliche Bitte um Grenzfälle verbessert die Abdeckung",
  "Specificity outperforms enthusiasm in cold outreach": "Konkretheit schlägt Begeisterung bei Kaltakquise",
  "Goal-anchored planning beats idea dumps": "Zielbasierte Planung schlägt Ideenhaufen",
  "Requesting alternatives counters fixation": "Die Bitte um Alternativen wirkt Fixierung entgegen",
  "Citation requirements reduce unsupported claims": "Quellenpflicht verringert unbelegte Behauptungen",
  "Grounding in supplied sources reduces hallucination; tell it to admit gaps.": "Die Verankerung in mitgelieferten Quellen verringert Halluzinationen; sag ihm, es soll Lücken zugeben.",
