  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "Studio zeichnet auf dem Prozessor (langsam). Dieses Handy hat einen Grafikchip – probier ihn aus: Bilder und ×4-Schärfung gehen dort um ein Vielfaches schneller.",
