  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "Aus der Notizbuch-App des Handys: Öffne eine Notiz (oder wähle mehrere) → Teilen → Attune → „Im Regal speichern“. Oder wähle hier exportierte Dateien: Text, Word, PDF, Webseiten, Google Keep, Evernote, eine .zip oder Fotos von Notizen.",
  "Versions & prices": "Versionen & Preise",
  "Pros & cons": "Vor- & Nachteile",
  "Compare with rivals": "Mit Konkurrenten vergleichen",
  "Latest news": "Neueste Nachrichten",
  "Those results were off-topic — searching another way…": "Diese Ergebnisse passten nicht zum Thema – es wird anders gesucht…",
  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "Dazu wurde nichts gefunden – nimm auch den Namen des Gebiets dazu (z. B. „… Neu-Kairo“) oder verschiebe die Karte dorthin und suche erneut.",
  "from the map's centre": "von der Kartenmitte",
  "saved place": "gespeicherter Ort",
  "Save this place": "Diesen Ort speichern",
  "This phone can't share its location with the app.": "Dieses Handy kann seinen Standort nicht an die App weitergeben.",
  "Location is off for Attune — allow it in the phone's settings to see where you are.": "Der Standort ist für Attune aus – erlaube ihn in den Einstellungen des Handys, um zu sehen, wo du bist.",
  "Couldn't get your location — check that location is on.": "Dein Standort konnte nicht ermittelt werden – prüfe, ob der Standort eingeschaltet ist.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "„{n}“ ist nicht mehr auf diesem Handy gespeichert – wähle die Datei erneut.",
  "tap to continue": "tippen zum Fortfahren",
  "The text and your questions are kept on this phone only. Forget removes them.": "Der Text und deine Fragen bleiben nur auf diesem Handy. „Vergessen“ entfernt sie.",
  "Web · Auto": "Web · Auto",
  "Web: Auto — it searches only when a question needs fresh facts": "Web: Auto – es sucht nur, wenn eine Frage aktuelle Fakten braucht",
  "Pick the best model for each question": "Für jede Frage das beste Modell wählen",
  "Reading your {f} conversation…": "Dein {f}-Gespräch wird gelesen…",
  "Reading the conversation…": "Das Gespräch wird gelesen…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "Geteilte Links werden in der Android-App geöffnet – oder füge hier den Text des Gesprächs ein.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "Ich habe dein Gespräch mit {f}{t} gelesen (etwa {n} Wörter). Frag mich alles dazu – prüfen, zusammenfassen oder dort weitermachen, wo es aufgehört hat.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · die KI läuft auf deinem Gerät · kein Konto, keine Anmeldung · Websuche nur, wenn eine Frage sie braucht (Auto) – schalte sie mit der Web-Taste aus",
  "Web: Off — nothing is looked up": "Web: Aus – nichts wird nachgeschlagen",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "Auch wenn Web im Chat aus ist, werden Fragen zu Preisen, Spezifikationen, Nachrichten, Ergebnissen oder diesem Jahr nachgeschlagen (nur die Suchwörter verlassen das Handy). Aus: Es wird nichts nachgeschlagen, solange du Web nicht einschaltest.",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "Das Modell hat Unsinn geschrieben – es wird im abgesicherten Modus neu gestartet und die Frage erneut gestellt…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "Dieses Modell schreibt auf diesem Handy Unsinn, auch im abgesicherten Modus. Wähle in Engine ein anderes Modell (Core funktioniert gut) und sag uns, welches versagt hat.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "Der abgesicherte Modus ist für dieses Modell an: Es hat auf diesem Handy einmal Unsinn geschrieben, deshalb läuft es ohne Tempo-Tricks und mit Speicher in voller Genauigkeit (etwas langsamer, gleiche Antworten).",
  "Turn safe mode off": "Abgesicherten Modus ausschalten",
  "Or any topic you like": "Oder ein beliebiges Thema",
  "I can answer about your next period, being late, ovulation, the fertile window, cycle and period length, your history and symptoms.": "Ich kann zu deiner nächsten Periode, Verspätung, Eisprung, dem fruchtbaren Fenster, Zyklus- und Periodenlänge, deinem Verlauf und deinen Symptomen antworten.",
