  "Update the map of {c} to the data of {d}? {s} — on Wi-Fi is best. The old map works until the new one is ready.": "Die Karte von {c} auf die Daten vom {d} aktualisieren? {s} – am besten im WLAN. Die alte Karte funktioniert, bis die neue bereit ist.",
  "Download the whole map of {c}? {s} — on Wi-Fi is best. Every road, building, place and shop, and offline search.": "Die ganze Karte von {c} herunterladen? {s} – am besten im WLAN. Jede Straße, jedes Gebäude, jeder Ort und jedes Geschäft, plus Offline-Suche.",
